command:
tmp=$(mktemp -d); export PMW_HOME="$tmp/home" PMW_PROJECT_SLUG=image-audit-3x; mkdir -p "$PMW_HOME/projects/image-audit-3x"; python3 - "$tmp" <<'PY'
import pathlib, struct, sys, zlib
root=pathlib.Path(sys.argv[1])
def png(path,w,h):
    raw=b''.join(b'\x00'+b'\xff\xff\xff'*w for _ in range(h))
    def chunk(t,d):
        return struct.pack('>I',len(d))+t+d+struct.pack('>I',zlib.crc32(t+d)&0xffffffff)
    path.write_bytes(b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack('>IIBBBBB',w,h,8,2,0,0,0))+chunk(b'IDAT',zlib.compress(raw,1))+chunk(b'IEND',b''))
png(root/'ref.png',1179,2556)
for name,w,h in [('a.png',862,1825),('b.png',851,1849),('c.png',945,2048)]:
    png(root/name,w,h)
PY
bin/pmw-image-audit baseline --reference "$tmp/ref.png" --register >/dev/null; for img in a.png b.png c.png; do set +e; out=$(bin/pmw-image-audit audit --reference "$tmp/ref.png" --image "$tmp/$img" --json); code=$?; set -e; printf '%s\n' "$out"; test "$code" = 2 || exit 1; printf '%s' "$out" | grep '"verdict": "需要重出"' >/dev/null || exit 1; printf '%s' "$out" | grep '"target_width": 1179' >/dev/null || exit 1; printf '%s' "$out" | grep '"target_height": 2556' >/dev/null || exit 1; done; rm -rf "$tmp"
